// Generates SCSS variables + CSS custom properties from src/design/tokens.ts.
// Usage: pnpm --filter web run tokens   (Node 26 strips the types natively: no tsx needed)
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { tokens } from '../src/design/tokens.ts';

const kebab = (s: string): string => s.replace(/([a-z])([A-Z0-9])/g, '$1-$2').toLowerCase();
const px = (n: number): string => (n === 0 ? '0' : `${n}px`);
const HEADER =
  '// AUTO-GENERATED by scripts/generate-tokens.ts — DO NOT EDIT.\n' +
  '// Edit src/design/tokens.ts then run `pnpm --filter web run tokens`.\n';

const scss: string[] = [HEADER];
const vars: string[] = [HEADER, ':root {', '  color-scheme: dark;'];

const add = (name: string, value: string): void => {
  scss.push(`$${name}: ${value};`);
  vars.push(`  --dl-${name}: ${value};`);
};

scss.push('\n// Color');
for (const [k, v] of Object.entries(tokens.color)) add(`color-${kebab(k)}`, v);

scss.push('\n// Font');
for (const [k, v] of Object.entries(tokens.font)) add(`font-${k}`, v);

scss.push('\n// Type — (size, line-height, weight, letter-spacing) · use @include type($type-…)');
for (const [k, t] of Object.entries(tokens.type)) {
  const ls = t.ls === 0 ? '0' : `${t.ls}px`;
  scss.push(`$type-${kebab(k)}: (${px(t.size)}, ${px(t.lh)}, ${t.w}, ${ls});`);
}

scss.push('\n// Space (4px scale)');
for (const [k, v] of Object.entries(tokens.space)) add(`space-${k}`, px(v));

scss.push('\n// Radius');
for (const [k, v] of Object.entries(tokens.radius)) add(`radius-${k}`, px(v));

scss.push('\n// Shadow');
for (const [k, v] of Object.entries(tokens.shadow)) add(`shadow-${kebab(k)}`, v);

scss.push('\n// Motion');
for (const [k, v] of Object.entries(tokens.motion.ease)) add(`ease-${k}`, v);
for (const [k, v] of Object.entries(tokens.motion.dur)) add(`dur-${k}`, `${v}ms`);

scss.push('\n// Opacity');
for (const [k, v] of Object.entries(tokens.opacity)) add(`opacity-${kebab(k)}`, String(v));

scss.push('\n// Breakpoints (SCSS only — CSS vars do not work in media queries)');
for (const [k, v] of Object.entries(tokens.breakpoint)) scss.push(`$bp-${k}: ${px(v)};`);

scss.push('\n// Layout');
for (const [k, v] of Object.entries(tokens.layout)) add(`layout-${kebab(k)}`, px(v));

vars.push('}');

const out = resolve(import.meta.dirname, '../src/styles/tokens');
writeFileSync(`${out}/_tokens.scss`, scss.join('\n') + '\n');
writeFileSync(`${out}/_vars.scss`, vars.join('\n') + '\n');
console.log('✔ tokens generated → src/styles/tokens/_tokens.scss, _vars.scss');
